500	// makes them a member with the invite's role and gives them a first API key.
501	func (s *Store) AcceptInvite(token, name string, now time.Time) (User, Member, APIKey, error) {
502		s.mu.Lock()
503		defer s.mu.Unlock()
504		var inv Invite
505		found := false
506		for _, i := range s.invites {
507			if i.Token == token && token != "" {
508				inv, found = i, true
509				break
510			}
511		}
512		// An invite is single-use: once accepted (or revoked) its token no longer creates a membership, so a removed
513		// member cannot re-join through their old token without a seat check.
514		if !found || inv.RevokedAt != nil || inv.AcceptedAt != nil {
515			return User{}, Member{}, APIKey{}, ErrNotFound
516		}
517		var u User
518		if id, ok := s.usersByEmail[normEmail(inv.Email)]; ok {
519			u = s.users[id]
520		} else {
521			name = strings.TrimSpace(name)
522			if name == "" {
523				return User{}, Member{}, APIKey{}, invalid("a new user needs a name")
524			}
525			u = User{ID: s.newID("usr"), Email: inv.Email, Name: name, CreatedAt: now.UTC()}
526			s.users[u.ID] = u
527			s.usersByEmail[normEmail(u.Email)] = u.ID
528		}
529		m, err := s.addMember(inv.OrgID, u.ID, inv.Role, now)
530		if err != nil {
531			return User{}, Member{}, APIKey{}, err
532		}
533		k, err := s.createAPIKey(inv.OrgID, u.ID, "Default", now)
534		if err != nil {
535			return User{}, Member{}, APIKey{}, err
536		}
537		t := now.UTC()
538		inv.AcceptedAt = &t
539		s.invites[inv.ID] = inv
540		return u, m, k, nil
541	}
